def backfill_jobs(apps, schema_editor):
    """Give pre-existing uploads a terminal job so the API/admin treat every upload uniformly."""
    UploadedImage = apps.get_model('detector', 'UploadedImage')
    AnalysisJob = apps.get_model('detector', 'AnalysisJob')
    done = {'completed': 'COMPLETED', 'no_face': 'COMPLETED'}
    for up in UploadedImage.objects.filter(job__isnull=True).iterator():
        status = done.get(up.processing_status, 'FAILED')
        AnalysisJob.objects.create(
            upload=up, status=status, attempts=1, finished_at=up.uploaded_at,
            error_code='' if status == 'COMPLETED' else 'LEGACY',
            error_message='' if status == 'COMPLETED' else 'Processed before background jobs existed.')


